const fs = require('fs');
const path = require('path');

const BASE = '/Users/bymyway/.openclaw/workspace';
const MEMORY_DIR = path.join(BASE, 'memory');
const PROFILE = path.join(BASE, 'CLIENT_PROFILE.md');
const HEARTBEAT = path.join(BASE, 'HEARTBEAT.md');

