  /^OpenClaw 執行心跳檢查，回報結果：cron 正常/i,
  /^OpenClaw 分析.*並識別.*已處理/i,
  /context overflow/i,
  /session restart/i,
];

const entries = [];
const lobsterPat = /🦞 小龍蝦：([\s\S]*?)(?=👤 教練：|---|$)/g;
let m;
while ((m = lobsterPat.exec(content)) !== null) {
  const section = m[1];
